        "bullets": [],
        "tables": [],
        "additionalText": "You cannot entirely prevent EGR operation, but you can significantly reduce the rate of carbon build-up by following these specialist recommendations. 01 Regular long drives Ensure the vehicle regularly completes journeys of at least 20–30 minutes at sustained speeds. This allows the engine to reach optimal operating temperature, helping to burn off light carbon deposits naturally. 02 The “Italian Tune-Up” Occasionally driving the vehicle in a lower gear at higher RPMs (safely and legally) can help increase exhaust temperatures and clear minor soot accumulation. 03 Use quality fuel Premium diesel fuels often contain higher levels of detergents designed to keep the fuel system and intake cleaner. 04 Address faults promptly A faulty injector or leaking turbo seal will dump excess oil or fuel into the intake, accelerating EGR carbon build-up exponentially. PREVENTATIVE MAINTENANCE £0–£150 Regular motorway drives + quality fuel VS CATASTROPHIC FAILURE – EGR + DPF + TURBO £3,000+ Full system replacement Prevention is always cheaper than replacement. FREQUENTLY ASKED QUESTIONS"
