        "tables": [],
        "additionalText": "A systematic approach helps identify the real cause of engine vibration. 1 Check for fault codes Scan with an OBD2 reader for pending or active trouble codes. 2 Visual inspection Inspect hoses, mounts, wiring and visible mechanical components. 3 Test engine mounts Check for collapsed rubber, excessive movement or hydraulic leakage. 4 Check fuel & ignition Examine spark plugs, coil packs, and injector spray balances. 5 Inspect clutch & drivetrain Check DMF play, drive shafts, universal joints, and gearbox bushes. Diagnostic rule: \"Never replace engine mounts based on vibration alone. A misfire can feel like a shaky engine mount at idle. Always do an OBD2 scan first - it's £50-£120 and will tell you if there's a misfire code before you spend £150-£500 on mounts that won't fix the problem.\" REPAIR OR REPLACE?"
