    "faqs": [
      {
        "question": "What causes engine vibration?",
        "answer": "The most common cause is worn engine mounts (£150-£500). A misfire can also cause idle vibration - an OBD2 scan (£50-£120) will confirm which."
      },
      {
        "question": "Is engine vibration always serious?",
        "answer": "Not always. Worn engine mounts create uncomfortable vibrations in the cabin but rarely cause immediate catastrophic failure. However, vibration accompanied by a flashing engine management light or severe knocking indicates major internal failure and requires immediate stoppage."
      },
      {
        "question": "How much does it cost to fix engine vibration?",
        "answer": "Spark plugs: £50-£150. Ignition coil: £70-£220. Fuel injector: £120-£900. Dual-mass flywheel (DMF): £500-£1,500. Diagnostic first (£50-£120) - don't guess."
      },
      {
        "question": "Can I still drive with engine vibration?",
        "answer": "Vibration at idle (mounts) - yes, but book diagnostic. Vibration under acceleration with flashing EML - no, stop immediately. Constant heavy vibration that worsens with revs - no, stop immediately - internal engine failure."
      },
      {
        "question": "Which engines are most prone to vibration?",
        "answer": "Based on KNOWN FAILURE PATTERNS, the Land Rover 306DT (SDV6/TDV6) - 980 quote requests [EM-VERIFIED] - is known for crankshaft bearing failure. BMW N47 (timing chain/injectors) and Mercedes OM651 (injector seals) are also commonly observed."
      },
      {
        "question": "Should I repair or replace the engine?",
        "answer": "If vibration is caused by mounts, misfires, or flywheels, repair is almost always the right financial choice (£150-£1,500). If internal engine failure (crankshaft or conrod) has occurred, evaluate vehicle value: under £4,000 often warrants replacement or scrapping, whereas vehicles over £8,000 justify a reconditioned engine replacement."
      }
    ]
