        "additionalText": "Neglecting injector symptoms leads to compounding secondary failures. Stage Damage Cost to Fix Stage 1 Injector wear - poor atomisation, reduced MPG £50 - £150 Stage 2 Injector stuck open - black smoke, fuel in oil £300 - £900 Stage 3 Oil dilution - fuel in oil destroys bearings £800 - £2,000+ Stage 4 DPF damage - over-fuelling destroys DPF £1,000 - £3,500+ Stage 5 Engine seizure - bearings fail, engine locks up £3,000 - £10,000+ Real-world example from specialist forums (anonymised): 2012 BMW 320d N47, 112,000 miles. Owner ignored rough idle and black smoke for 3 months. A stuck-open injector dumped fuel into cylinder #3, washing the cylinder walls and diluting the engine oil. The diluted oil destroyed the main bearings. Total cost: £4,800 for a reconditioned engine. The same owner could have paid £450 for one reconditioned injector 10 weeks earlier. Red flag engines · injector failure patterns"
