        "tables": [],
        "additionalText": "Identify whether you are experiencing early oil delivery warnings or progressed mechanical damage. 🔶 Early Warning Signs (Act Immediately) Flickering Oil Light at Idle: Oil pressure warning light blinks when stationary at idle but extinguishes when revving above 1,500 RPM. Hydraulic Lifter Ticking: Tapping or clicking noises originating from the top of the cylinder head due to oil starvation at the camshafts. Low Oil Pressure Gauge: Analogue or digital dashboard oil pressure gauge registers below manufacturer operating threshold (under 1.5–2.0 bar warm). 🔴 Critical Progressed Damage (Stop Driving - Engine at Risk) Solid Oil Pressure Warning Light: Red oil can symbol remains illuminated permanently at all engine speeds. Loud Deep Rhythmic Knocking: Rhythmic heavy thudding under load indicates big-end rod bearing clearance failure. Engine Squeal or Sudden Drag: Friction welding between bearing surfaces causes sudden engine drag, loss of RPM, and burning oil smell. Engine Seizure / No Crank: Starter motor clicks but cannot turn the crankshaft due to seized bottom-end journals. 🚨 Critical Warning: If the red oil pressure warning light illuminates while driving, pull over safely at the earliest opportunity and shut off the ignition. Do not attempt to restart the engine to limp home or drive to a garage. Financial Impact"
