        "additionalText": "A competent specialist will never replace a head gasket without systematically identifying why the engine overheated first. Step Diagnostic Check / Procedure What Garage Identifies Typical Garage Fee 1 Coolant Level & Expansion Tank Inspection Checks for low fluid level, discoloured coolant, or air locks. £10 – £30 2 Pressurised Leak Detection Test Pressurises cooling circuit to 1.5 bar to locate weeping hoses or radiator core leaks. £50 – £200 3 Thermostat Opening Verification Measures top/bottom radiator hose temperature differential using infrared thermometer. £95 – £215 (fitted) 4 Electric Cooling Fan Circuit Activation Commands high-speed fan relay via OBD2 scan tool and tests A/C fan cycling. £150 – £450 5 Water Pump Flow & Weep Hole Test Verifies coolant return flow rate into expansion bottle and checks pump shaft play. £115 – £700 6 Chemical Block Sniffer Test Draws expansion tank air through chemical reagent; blue turns yellow if CO2 exhaust gas is present. £50 – £150 7 Cylinder Leak-Down & Compression Test Quantifies mechanical cylinder pressure loss directly into adjacent coolant jackets. £100 – £200 “ Specialist Rule of Thumb: 90% of overheating complaints on vehicles over 60,000 miles stem from either a stuck thermostat or a failed water pump impeller. If you are replacing the timing belt or timing chain, always replace both the water pump and thermostat simultaneously—the labour overlap saves hundreds of pounds. UK Market Statistics"
