        "bullets": [],
        "tables": [],
        "additionalText": "A timing belt rarely gives loud warning noises before snapping, but visual inspection and subtle cues can prevent catastrophic engine destruction. 🔍 Visible Surface Cracking Micro-cracking on the smooth outer rubber backing or between drive teeth upon flexing. ✨ Fraying or Glazing Shiny, glassy appearance on pulley contact edges or loose fabric cord fibres fraying. 🔔 Ticking from Timing Cover High-frequency ticking or scraping noise caused by slack belt flapping against plastic shroud. ⚡ Hard Starting & Misfires Belt has jumped 1–2 teeth due to lost tension, creating camshaft timing lag and misfires. 🔇 Engine Won't Crank / Spin Fast Starter motor spins freely and rapidly with no compression because the camshaft is motionless. 🚨 Critical Age Rule If overdue by mileage OR calendar years, replace immediately. Rubber perishes over time regardless of mileage. Known Failure Patterns — UK Risk Data"
