      {
        "title": "Preventative Timing Belt Maintenance: The Cheapest Insurance",
        "paragraphs": [
          "Every preventative step below costs a tiny fraction of what a snapped timing belt will cost in engine replacement."
        ],
        "bullets": [],
        "tables": [],
        "additionalText": "Every preventative step below costs a tiny fraction of what a snapped timing belt will cost in engine replacement. 01 Replace at Manufacturer Interval Never wait for symptoms or breakage. On interference engines, scheduled replacement is non-negotiable. 02 Replace Water Pump Simultaneously Water pump failure shortly after a belt change requires full disassembly labour again. Replace them together. 03 Use OEM / Premium Brand Belts Only Fitting unbranded cheap belts saves £30 but risks a £5,000 engine write-off. Fit Gates, Continental, or Dayco. 04 Replace Tensioner & Idler Pulleys Seized tensioner bearings cause over 40% of belt breakages. Always install a complete timing kit. 05 Assume Overdue on Used Cars If a newly purchased used vehicle lacks stamped service proof of a belt change, replace it immediately. Preventative Replacement £300–£800 Belt + tensioner kit, scheduled service VS Snapped Belt — Engine Replacement £2,500–£7,000+ Reconditioned engine or major rebuild The maths is simple — preventative maintenance is the ultimate financial protection. Frequently Asked Questions"
      }
