        "bullets": [],
        "tables": [],
        "additionalText": "While turbo failure can occur on any forced-induction vehicle, marketplace inquiry data highlights specific engine families with pronounced turbocharger replacement demand. BMW N47D20C (2.0L Diesel) 1,450 reqs £700 – £1,500 Frequent secondary turbo failure caused by timing chain metal debris in oil galleries; electronic actuator motor failure. Mercedes OM651 (2.1L Diesel) 1,250 reqs £600 – £1,400 Variable geometry turbo (VNT) vanes sticking due to diesel soot buildup; vacuum wastegate actuator diaphragm failure. Land Rover 204DTD Ingenium (2.0L) 1,150 reqs £800 – £1,800 Severe diesel fuel oil dilution degrading turbo lubrication film; rapid journal bearing degradation and boost loss. VW / Audi EA189 (2.0L TDI) 1,050 reqs £500 – £1,200 Excessive EGR soot accumulation choking VNT guide vanes; premature wastegate actuator electronic fault codes. BMW N57D30 (3.0L Inline-6) 830 reqs £1,200 – £2,500 Twin-turbo / tri-turbo setups require matched balancing; high oil feed pipe carbonisation under heavy engine load. Ford DV6 / 1.6 TDCi 780 reqs £450 – £900 Oil feed banjo bolt micro-filter mesh blocks with carbonised sludge, starving the turbocharger of lubrication within miles. Renault K9K (1.5 dCi) 730 reqs £600 – £1,500 Turbo failure secondary to diesel injector over-fuelling; oil carbonisation around centre bearing housing. Land Rover 306DT (3.0L SDV6) 980 reqs £1,200 – £2,800 Secondary turbo failure frequently paired with crankshaft main bearing wear; twin turbo isolation valve seizure. Economic Decision Framework"
